import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type GameShowIntroProps = Record<string, any>;

const GameShowIntro: React.FC<GameShowIntroProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "Malloy's Game Show",
  titleColor = "#FFD700",
  glowColor = "#FF00FF",
  bulbColorOn = "#FFFACD",
  bulbColorOff = "#554400",
  fontSize = 120,
  flashSpeed = 6,
}) => {
  useFontLoader(["Righteous"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency safely
  const bgColor = transparentBackground ? "#00000000" : backgroundColor;

  // Spring animation for entrance
  const scale = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  const opacity = interpolate(frame, [0, 10], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Flashing lights logic (Bulbs)
  // We toggle between two states every `flashSpeed` frames
  const isPhaseA = Math.floor(frame / flashSpeed) % 2 === 0;

  // Dynamic Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    width: "100%",
    height: "100%",
    fontFamily: "Righteous",
    perspective: "1000px",
  };

  // The "Marquee" Board Style
  const boardStyle: React.CSSProperties = {
    position: "relative",
    padding: "40px 80px",
    border: `8px dotted ${isPhaseA ? bulbColorOn : bulbColorOff}`,
    borderRadius: "20px",
    backgroundColor: "rgba(20, 20, 20, 0.8)",
    boxShadow: `0 0 50px ${glowColor}40`, // Ambient glow
    transform: `scale(${scale})`,
    opacity,
  };

  // Secondary border for the "chasing" effect simulation (offset dots)
  // We simulate "chasing" by having a second border that lights up when the first is off
  const secondaryBorderStyle: React.CSSProperties = {
    position: "absolute",
    top: -8,
    left: -8,
    right: -8,
    bottom: -8,
    border: `8px dotted ${isPhaseA ? bulbColorOff : bulbColorOn}`,
    borderRadius: "20px",
    pointerEvents: "none",
  };

  // Text Glow Animation
  const pulse = Math.sin(frame / 10);
  const glowIntensity = interpolate(pulse, [-1, 1], [20, 40]);

  const textStyle: React.CSSProperties = {
    fontSize: fontSize,
    color: titleColor,
    textAlign: "center",
    // Complex shadow for neon/bulb look
    textShadow: `
      0 0 10px ${titleColor},
      0 0 ${glowIntensity}px ${glowColor},
      0 0 ${glowIntensity * 2}px ${glowColor}
    `,
    lineHeight: 1.1,
    zIndex: 10,
    position: "relative",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={containerStyle}>
        
        {/* The Marquee Sign Board */}
        <div style={boardStyle}>
          {/* The Secondary "Chasing" Bulbs Layer */}
          <div style={secondaryBorderStyle} />

          {/* Main Title */}
          <h1 style={textStyle}>
            {titleText}
          </h1>

          {/* Decorative "Bulbs" simulation on the text itself? 
              Using a subtle overlay pattern to suggest texture */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              backgroundImage: "radial-gradient(circle, rgba(255,255,255,0.2) 2px, transparent 2.5px)",
              backgroundSize: "20px 20px",
              pointerEvents: "none",
              opacity: 0.5,
            }}
          />
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default GameShowIntro;